ftCommonData* p_ftCommonData;
static void cbst(HSD_MObj* m, HSD_TObj* t, u32 r) { T(7100); T(PI(m)); T(PI(t)); T(r); }
void HSD_TExpSetReg(HSD_TExp* t)
{
    HSD_TECnst* c = &t->cnst;
    int n = 0;
    T(1500);
    while (c != 0 && n++ < 4) {
        u8* v = (u8*) c->val;
        T(c->type); T(c->reg); T(c->comp); T(c->ctype); T(c->idx); T(PI(c->val));
        if (v != 0 && PI(v) == 0xFFFFFFFFu) { T(v[0]); if (c->comp == HSD_TE_RGB) { T(v[1]); T(v[2]); T(v[3]); } }
        c = (HSD_TECnst*) c->next;
    }
}
void HSD_SetupTevStage(HSD_TevDesc* d)
{
    T(1501); T(d->flags); T(d->stage); T(d->coord); T(d->map); T(d->color);
    T(d->u.tevconf.clr_op); T(d->u.tevconf.clr_a); T(d->u.tevconf.clr_b); T(d->u.tevconf.clr_c); T(d->u.tevconf.clr_d);
    T(d->u.tevconf.alpha_a); T(d->u.tevconf.alpha_b); T(d->u.tevconf.alpha_c); T(d->u.tevconf.alpha_d);
    T(d->u.tevconf.kcsel); T(d->u.tevconf.kasel);
}
void HSD_SetupRenderModeWithCustomPE(u32 rm, HSD_PEDesc* pe)
{
    T(1502); T(rm); T(PI(pe));
    if (pe != 0) {
        T(pe->flags); T(pe->type); T(pe->src_factor); T(pe->dst_factor); T(pe->logic_op); T(pe->z_comp);
        T(pe->alpha_comp0); T(pe->ref0); T(pe->alpha_op); T(pe->alpha_comp1); T(pe->ref1); T(pe->dst_alpha);
    }
}

static void world(void)
{
    int i, b;
    zero(GO, sizeof GO); zero(JO, sizeof JO); zero(FT, sizeof FT); zero(FDATA, sizeof FDATA); zero(&CD, sizeof CD);
    for (i = 0; i < NG; i++) fill_Fighter(&FT[i]);
    for (i = 0; i < NJ; i++) fill_HSD_JObj(&JO[i]);
    for (i = 0; i < NG; i++) fill_HSD_GObj(&GO[i]);
    for (i = 0; i < NG; i++) {
        GO[i].user_data = &FT[i];
        GO[i].hsd_obj = &JO[i];
        GO[i].classifier = HSD_GOBJ_CLASS_FIGHTER;
        GO[i].next = i + 1 < NG ? &GO[i + 1] : 0;
        FT[i].gobj = &GO[i];
        FT[i].ft_data = &FDATA[i];
        FT[i].grab_cb = cbev1; FT[i].grabbed_cb = cbev3;
        FT[i].kind = (FighterKind) ((u32) FT[i].kind % 27u); FT[i].player_id %= 4; FT[i].x618_player_id %= 4;
        for (b = 0; b < 64; b++) { if (b < NP) fill_FighterBone(&PARTS[i][b]); else { zero(&PARTS[i][b], sizeof PARTS[i][b]); PARTS[i][b].flags_b1 = 1; } PARTS[i][b].joint = &JO[(u32) (i * 5 + b * 3) % NJ]; }
        FT[i].parts = PARTS[i];
        { int pk = i * 24; FDATA[i].x0 = (void*) PADB[pk++]; FDATA[i].ext_attr = (void*) PADB[pk++]; FDATA[i].x8 = (void*) PADB[pk++]; FDATA[i].xC = (void*) PADB[pk++]; FDATA[i].x10 = (void*) PADB[pk++]; FDATA[i].x14 = (void*) PADB[pk++]; FDATA[i].x18 = (void*) PADB[pk++]; FDATA[i].x1C = (void*) PADB[pk++]; FDATA[i].x20 = (void*) PADB[pk++]; FDATA[i].x24 = (void*) PADB[pk++]; FDATA[i].x28 = (void*) PADB[pk++]; FDATA[i].x2C = (void*) PADB[pk++]; FDATA[i].x30 = (void*) PADB[pk++]; FDATA[i].x34 = (void*) PADB[pk++]; FDATA[i].x38 = (void*) PADB[pk++]; FDATA[i].x3C = (void*) PADB[pk++]; FDATA[i].x40 = (void*) PADB[pk++]; FDATA[i].x44 = (void*) PADB[pk++]; FDATA[i].x48_items = (void*) PADB[pk++]; FDATA[i].x4C_sfx = (void*) PADB[pk++]; FDATA[i].x50 = (void*) PADB[pk++]; FDATA[i].x54 = (void*) PADB[pk++]; FDATA[i].x58 = (void*) PADB[pk++]; FDATA[i].x5C = (void*) PADB[pk++]; }
    }
    for (i = 0; i < NJ; i++) {
        JO[i].parent = i ? &JO[(i - 1) / 2] : 0;
        JO[i].child = 2 * i + 1 < NJ ? &JO[2 * i + 1] : 0;
        JO[i].next = (i & 1) && i + 1 < NJ ? &JO[i + 1] : 0;
    }
    p_ftCommonData = &CD;
    for (i = 0; i < 16; i++) PLINKV[i] = 0;
    PLINKV[HSD_GOBJ_PLINK_FIGHTER] = &GO[0];
    HSD_GObjPLinkHead = PLINKV;
    for (i = 0; i < NG; i++) FT[i].x61A_controller_index %= 6;
    {
        static int regd_;
        int q_;
        if (!regd_) { regd_ = 1; preg(MO, sizeof MO); preg(TOBJ, sizeof TOBJ); preg(&SHAD, sizeof SHAD); preg(&TOON, sizeof TOON); preg(PE, sizeof PE); preg(MAT, sizeof MAT); preg(TXP, sizeof TXP); }
        zero(MO, sizeof MO); zero(MAT, sizeof MAT); zero(TOBJ, sizeof TOBJ); zero(&SHAD, sizeof SHAD); zero(&TOON, sizeof TOON); zero(PE, sizeof PE);
        zero(&MINFO, sizeof MINFO); zero(TXP, sizeof TXP); zero(&IMGD, sizeof IMGD);
        MINFO.setup_tev = cbst;
        for (q_ = 0; q_ < 3; q_++) {
            MO[q_].parent.class_info = (HSD_ClassInfo*) &MINFO;
            MO[q_].rendermode = rnd();
            MO[q_].mat = &MAT[q_];
            MAT[q_].ambient.r = (u8) fv(); MAT[q_].ambient.g = (u8) fv(); MAT[q_].ambient.b = (u8) fv(); MAT[q_].ambient.a = (u8) fv();
            MAT[q_].diffuse.r = (u8) fv(); MAT[q_].diffuse.g = (u8) fv(); MAT[q_].diffuse.b = (u8) fv(); MAT[q_].diffuse.a = (u8) fv();
            MAT[q_].specular.r = (u8) fv(); MAT[q_].specular.g = (u8) fv(); MAT[q_].specular.b = (u8) fv(); MAT[q_].specular.a = (u8) fv();
            MAT[q_].alpha = rg(); MAT[q_].shininess = rg();
            MO[q_].tobj = (fv() & 1) ? &TOBJ[q_] : 0;
            TOBJ[q_].next = (q_ < 2 && (fv() & 1)) ? &TOBJ[q_ + 1] : 0;
            MO[q_].pe = &PE[q_];
            PE[q_].flags = (u8) fv(); PE[q_].ref0 = (u8) fv();
        }
        tobj_shadows = (fv() & 1) ? &SHAD : 0;
        tobj_toon = (fv() & 1) ? &TOON : 0;
        TOON.imagedesc = (fv() & 1) ? &IMGD : 0;
        TOON.next = 0; SHAD.next = 0;
        ft_804D6580 = &MO[1]; ft_804D6588 = &MO[2];
        TXP[0].cnst.reg = (u8) fv(); TXP[0].cnst.type = HSD_TE_CNST; TXP[0].cnst.comp = (u8) (fv() & 7);
        { u8* cp_ = (u8*) &CD.x6D8; for (q_ = 0; q_ < 24; q_++) cp_[q_] = (u8) fv(); }
    }
}
static void hworld(void)
{
    int i, b;
    for (i = 0; i < NG; i++) hash_Fighter(&FT[i]);
    for (i = 0; i < NJ; i++) hash_HSD_JObj(&JO[i]);
    for (i = 0; i < NG; i++) hash_HSD_GObj(&GO[i]);
    for (i = 0; i < NG; i++) for (b = 0; b < NP; b++) hash_FighterBone(&PARTS[i][b]);
    { int q_; for (q_ = 0; q_ < 3; q_++) HM(PI(TOBJ[q_].next)); HM(PI(SHAD.next)); HM(PI(TOON.next)); }
}

int main(void)
{
    int op, k;
    preg(GO, sizeof GO); preg(JO, sizeof JO); preg(FT, sizeof FT); preg(FDATA, sizeof FDATA); preg(PADB, sizeof PADB);
    freg((const void*) cbev1); freg((const void*) cbev2); freg((const void*) cbp1); freg((const void*) cbp2); freg((const void*) cbev3);
    for (op = 0; op < 4; op++) {
        for (k = 0; k < 600; k++) {
            u32 ret = 0;
            tu_case(op, k);
            world();
            ASRT_ARMED = 1;
            if (_setjmp(ASRT_JB, 0) != 0) { printf("%d %d ASSERT%c", op, k, 10); fflush(0); continue; }
            {
                int gi = (int) (rnd() % NG);
                Fighter_GObj* g = &GO[gi];
                Fighter* fp = &FT[gi];
                (void) g; (void) fp;
                switch (op) {
                case 0: { ftMaterial_800BF260(); HM(ftMObj.setup != 0); }; break;
                case 1: { HSD_MObj* mo_ = &MO[fv() % 3]; u32 rm_ = rnd(); u32 un_ = fv(); HSD_GObj_804D7814 = g; ftMaterial_800BF2B8(mo_, rm_, un_); }; break;
                case 2: { HSD_MObj* mo_ = &MO[fv() % 3]; u32 rm_ = rnd(); HSD_TExp tx_; HSD_TExp* r_; zero(&tx_, sizeof tx_); r_ = ftMaterial_800BF534(fp, mo_, &tx_, rm_); ret = (u32) (r_ != 0); HM(tx_.cnst.reg); HM(tx_.cnst.comp); HM(tx_.cnst.idx); HM(PI(tx_.cnst.val)); HM(tx_.cnst.type); }; break;
                case 3: { HSD_MObj* mo_ = &MO[fv() % 3]; HSD_TExp* tp_ = (fv() & 1) ? &TXP[0] : 0; ftMaterial_800BF6BC(fp, mo_, tp_); }; break;
                }
            }
            hworld();
            ASRT_ARMED = 0;
            printf("%d %d %08X %08X %08X\n", op, k, ret, H, TR);
            fflush(0);
        }
    }
    return 0;
}
